create or replace view IDQ_PRODUCTION.EKS_CALCULATION.SVMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NOTMANTAINED_SEL_1(
	NEGOTIATINGCOUNTRY,
	BUYERSHORTSIGN,
	BUYERFIRSTNAME,
	BUYERLASTNAME,
	ZMATKL,
	ARTICLEFAMILY,
	BA_ITEMNO,
	BA_DESCRIPTION,
	SK_ITEMNO,
	SK_DESCRIPTION_INT,
	ITEMID,
	ITEMNO,
	ARTICLETYPE,
	DESCRIPTION,
	LISTINGOVERVIEWID,
	SUPPLIERNO,
	SUPPLIERDESCRIPTION,
	RECEIVINGCOUNTRY,
	ZRELEVANTMDM,
	ZSOURCE,
	ZACTIVE
) as
(SELECT DISTINCT EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.NegotiatingCountry, EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.BuyerSHORTSIGN, EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.BuyerFirstName, EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.BuyerLastName, EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.zMATKL, EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.articlefamily, EKS_CALCULATION.svMARA_EKS_ITEM_BASKEA_Structure_010.BA_ITEMNO, EKS_CALCULATION.svMARA_EKS_ITEM_BASKEA_Structure_010.BA_Description, EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.sk_itemno, EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.SK_DESCRIPTION_INT, EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.ITEMID, EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.ITEMNO, EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.ArticleType, EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.DESCRIPTION, EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.LISTINGOVERVIEWID, EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.SUPPLIERNO, EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.SUPPLIERDESCRIPTION, EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.ReceivingCountry, EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.zRelevantMDM, EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.zSource, EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.zActive
FROM     EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010_1 LEFT OUTER JOIN
 EKS_CALCULATION.svMARA_EKS_ITEM_BASKEA_Structure_010_1 ON EKS_CALCULATION.svMARA_EKS_ITEM_BASKEA_Structure_010.EA_ITEMNO = EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.ITEMNO AND EKS_CALCULATION.svMARA_EKS_ITEM_BASKEA_Structure_010.SK_ITEMNO = EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.sk_itemno LEFT OUTER JOIN EKS_CALCULATION.EKS_ZSM_ExcludeList_1 ON EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.ITEMNO = EKS_CALCULATION.EKS_ZSM_ExcludeList.ITEMNO AND ( ( EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.SupplierNo = EKS_CALCULATION.EKS_ZSM_ExcludeList.SUPPLIERNO AND EKS_CALCULATION.EKS_ZSM_ExcludeList.LISTINGOVERVIEWID IS NULL ) OR ( EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.LISTINGOVERVIEWID = EKS_CALCULATION.EKS_ZSM_ExcludeList.LISTINGOVERVIEWID AND EKS_CALCULATION.EKS_ZSM_ExcludeList.SupplierNo IS NULL ) OR ( EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.SupplierNo = EKS_CALCULATION.EKS_ZSM_ExcludeList.SUPPLIERNO AND EKS_CALCULATION.svMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NotMantained_010.LISTINGOVERVIEWID = EKS_CALCULATION.EKS_ZSM_ExcludeList.LISTINGOVERVIEWID ) OR ( EKS_CALCULATION.EKS_ZSM_ExcludeList.SupplierNo IS NULL AND EKS_CALCULATION.EKS_ZSM_ExcludeList.LISTINGOVERVIEWID IS NULL ) ) AND EKS_CALCULATION.EKS_ZSM_ExcludeList.REPORTNO = '046'
  WHERE  ( EKS_CALCULATION.EKS_ZSM_ExcludeList.ITEMNO IS NULL ) 
);